settings.custom-liquid:
{% comment %}
  Plantilla: Nuestras Tiendas Axspen
  Diseño moderno, legible y responsivo.
{% endcomment %}

{% assign stores_data = "Ferias|Calle 72 # 69M – 33|Bogotá,Centro Comercial Plaza Imperial|Cra. 104 #148 – 07 local 1-46|Bogotá,Centro Comercial Ventura Terreros|Carrera 1 # 38 – 53 Tienda 2-41|Soacha,Bosa|Kra 80c 65-29 sur|Bogotá,San Mateo|AC 30 # 1-30|Soacha,Venecia|Diagonal 45 # 53 – 43 sur|Bogotá,Centro Comercial Salitre Plaza|Cra 68b #24-39 Local 168|Bogotá,Centro Comercial Hayuelos|Calle 20 # 82- 52 Local 2-74|Bogotá,Perdomo|Calle 63 sur #71h-15 Barrio perdomo|Bogotá,Centro Comercial Plaza de las Américas|Calle 6 sur #71D-43|Bogotá,Centro Comercial Nuestro Bogotá|Ak 86 # 55A – 75 Local L2-017|Bogotá" | split: "," %}

<div class="our-stores-wrapper">
  <div class="our-stores-container">

    <!-- Encabezado -->
    <header class="our-stores-header">
      <div class="our-stores-badge">
        <svg class="badge-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
        </svg>
        <span>Puntos Físicos</span>
      </div>
      <h1 class="our-stores-title">Nuestras Tiendas</h1>
      <p class="our-stores-subtitle">Encuentra tu tienda física más cercana, visítanos y vive la experiencia Axspen.</p>

      <!-- Buscador -->
      <div class="store-search-box">
        <svg class="search-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
        </svg>
        <input 
          type="text" 
          id="storeSearchInput" 
          class="store-search-input" 
          placeholder="Buscar por tienda, centro comercial o dirección..." 
          aria-label="Buscar tienda"
        />
        <button type="button" id="clearStoreSearch" class="search-clear-btn" aria-label="Limpiar búsqueda" style="display: none;">
          &times;
        </button>
      </div>

      <div class="store-results-count" id="storesCount">
        Mostrando <strong id="visibleCountNumber">{{ stores_data.size }}</strong> tiendas
      </div>
    </header>

    <!-- Grid de Tiendas -->
    <div class="stores-grid" id="storesGrid">
      {% for item in stores_data %}
        {% assign store = item | split: "|" %}
        {% assign store_name = store[0] %}
        {% assign store_address = store[1] %}
        {% assign store_city = store[2] | default: "Bogotá" %}
        {% assign query_address = store_name | append: " " | append: store_address | append: " Colombia" | url_encode %}

        <article class="store-card" data-name="{{ store_name | downcase }}" data-address="{{ store_address | downcase }}" data-city="{{ store_city | downcase }}">

          <div class="store-card-header">
            <div class="store-tag">{{ store_city }}</div>
            <h2 class="store-name">{{ store_name }}</h2>
          </div>

          <!-- Mapa con ubicación -->
          <div class="store-map-wrapper">
            <iframe 
              title="Mapa de {{ store_name }}"
              src="https://maps.google.com/maps?q={{ query_address }}&t=&z=15&ie=UTF8&iwloc=&output=embed"
              class="store-map-iframe"
              loading="lazy" 
              allowfullscreen="" 
              referrerpolicy="no-referrer-when-downgrade">
            </iframe>
          </div>

          <!-- Dirección -->
          <div class="store-card-body">
            <div class="store-info-row">
              <div class="store-icon-wrapper">
                <svg class="store-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
              </div>
              <div class="store-info-text">
                <span class="store-info-label">Dirección:</span>
                <span class="store-address-text">{{ store_address }}</span>
              </div>
            </div>
          </div>

          <!-- Botones -->
          <div class="store-card-footer">
            <a 
              href="https://www.google.com/maps/search/?api=1&query={{ query_address }}" 
              target="_blank" 
              rel="noopener noreferrer" 
              class="btn-store btn-primary"
            >
              <svg class="btn-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
              <span>Cómo llegar</span>
            </a>

            <button 
              type="button" 
              class="btn-store btn-secondary copy-btn" 
              data-copy="{{ store_address }}"
              title="Copiar dirección"
            >
              <svg class="btn-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
              <span class="copy-text">Copiar</span>
            </button>
          </div>

        </article>
      {% endfor %}
    </div>

    <div id="noResults" class="stores-no-results" style="display: none;">
      <div class="no-results-icon">
        <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="no-results-title">No encontramos tiendas con esa búsqueda</p>
      <p class="no-results-sub">Prueba con otro término como el nombre del centro comercial o barrio.</p>
      <button type="button" class="btn-store btn-primary reset-search-btn" id="resetSearchBtn">Ver todas las tiendas</button>
    </div>

  </div>
</div>

<style>
  .our-stores-wrapper {
    padding: 60px 20px 90px;
    background: #f8fafc;
    color: #1e293b;
    font-family: inherit;
  }
  .our-stores-container {
    max-width: 1320px;
    margin: 0 auto;
  }
  .our-stores-header {
    text-align: center;
    margin-bottom: 50px;
  }
  .our-stores-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: #e0f2fe;
    color: #0369a1;
    font-size: 1.4rem;
    font-weight: 700;
    padding: 6px 16px;
    border-radius: 9999px;
    margin-bottom: 16px;
    letter-spacing: 0.02em;
    text-transform: uppercase;
  }
  .badge-icon {
    width: 18px;
    height: 18px;
  }
  .our-stores-title {
    font-size: 3.8rem;
    font-weight: 800;
    color: #0f172a;
    margin: 0 0 14px 0;
    letter-spacing: -0.03em;
    line-height: 1.2;
  }
  .our-stores-subtitle {
    font-size: 1.8rem;
    color: #475569;
    margin: 0 auto 30px;
    line-height: 1.5;
    max-width: 650px;
  }
  .store-search-box {
    position: relative;
    max-width: 580px;
    margin: 0 auto 16px;
  }
  .store-search-input {
    width: 100%;
    padding: 18px 50px 18px 56px;
    border-radius: 9999px;
    border: 2px solid #cbd5e1;
    font-size: 1.6rem;
    background: #ffffff;
    box-shadow: 0 4px 14px rgba(0,0,0,0.05);
    outline: none;
    transition: all 0.25s ease;
    box-sizing: border-box;
    color: #0f172a;
  }
  .store-search-input:focus {
    border-color: #0f172a;
    box-shadow: 0 0 0 4px rgba(15, 23, 42, 0.12);
  }
  .search-icon {
    position: absolute;
    left: 20px;
    top: 50%;
    transform: translateY(-50%);
    width: 24px;
    height: 24px;
    color: #64748b;
    pointer-events: none;
  }
  .search-clear-btn {
    position: absolute;
    right: 18px;
    top: 50%;
    transform: translateY(-50%);
    background: #e2e8f0;
    border: none;
    border-radius: 50%;
    width: 28px;
    height: 28px;
    font-size: 20px;
    line-height: 1;
    color: #475569;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
  }
  .search-clear-btn:hover {
    background: #cbd5e1;
    color: #0f172a;
  }
  .store-results-count {
    font-size: 1.5rem;
    color: #64748b;
    margin-top: 10px;
  }
  .store-results-count strong {
    color: #0f172a;
  }
  .stores-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(370px, 1fr));
    gap: 30px;
  }
  .store-card {
    background: #ffffff;
    border-radius: 20px;
    border: 1px solid #e2e8f0;
    padding: 26px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    box-shadow: 0 4px 18px -2px rgba(0,0,0,0.06);
    transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  }
  .store-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 20px 32px -8px rgba(0,0,0,0.12);
    border-color: #cbd5e1;
  }
  .store-card-header {
    margin-bottom: 16px;
  }
  .store-tag {
    display: inline-block;
    font-size: 1.2rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    background: #f1f5f9;
    color: #475569;
    padding: 4px 10px;
    border-radius: 6px;
    margin-bottom: 8px;
  }
  .store-name {
    font-size: 2.2rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0;
    line-height: 1.35;
  }
  .store-map-wrapper {
    width: 100%;
    height: 190px;
    border-radius: 14px;
    overflow: hidden;
    margin-bottom: 20px;
    background: #e2e8f0;
    border: 1px solid #cbd5e1;
  }
  .store-map-iframe {
    width: 100%;
    height: 100%;
    border: 0;
    display: block;
  }
  .store-card-body {
    flex-grow: 1;
    margin-bottom: 24px;
  }
  .store-info-row {
    display: flex;
    align-items: flex-start;
    gap: 14px;
  }
  .store-icon-wrapper {
    background: #e0f2fe;
    color: #0284c7;
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .store-icon {
    width: 22px;
    height: 22px;
  }
  .store-info-text {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .store-info-label {
    font-size: 1.3rem;
    color: #64748b;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .store-address-text {
    font-size: 1.6rem;
    color: #1e293b;
    line-height: 1.5;
    font-weight: 600;
  }
  .store-card-footer {
    display: flex;
    gap: 12px;
    margin-top: auto;
  }
  .btn-store {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 14px 20px;
    border-radius: 12px;
    font-size: 1.5rem;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.2s ease;
    border: none;
    box-sizing: border-box;
    line-height: 1;
  }
  .btn-primary {
    background: #0f172a;
    color: #ffffff !important;
    flex: 1;
  }
  .btn-primary:hover {
    background: #334155;
    transform: translateY(-1px);
  }
  .btn-secondary {
    background: #f1f5f9;
    color: #1e293b;
    border: 1px solid #cbd5e1;
  }
  .btn-secondary:hover {
    background: #e2e8f0;
    color: #0f172a;
  }
  .btn-icon {
    width: 20px;
    height: 20px;
    min-width: 20px;
  }
  .stores-no-results {
    text-align: center;
    padding: 60px 20px;
    background: #ffffff;
    border-radius: 20px;
    border: 1px solid #e2e8f0;
    max-width: 600px;
    margin: 40px auto;
  }
  .no-results-icon {
    color: #94a3b8;
    margin-bottom: 16px;
  }
  .no-results-title {
    font-size: 2.2rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 10px;
  }
  .no-results-sub {
    font-size: 1.6rem;
    color: #64748b;
    margin: 0 0 24px;
  }
  .reset-search-btn {
    display: inline-flex;
    padding: 14px 28px;
  }
  @media (max-width: 768px) {
    .our-stores-wrapper {
      padding: 40px 16px 60px;
    }
    .our-stores-title {
      font-size: 3rem;
    }
    .our-stores-subtitle {
      font-size: 1.6rem;
    }
    .stores-grid {
      grid-template-columns: 1fr;
      gap: 20px;
    }
    .store-card {
      padding: 20px;
    }
    .store-name {
      font-size: 2rem;
    }
    .store-address-text {
      font-size: 1.5rem;
    }
    .btn-store {
      font-size: 1.4rem;
      padding: 12px 16px;
    }
  }
</style>

<script>
  (function() {
    const searchInput = document.getElementById("storeSearchInput");
    const clearBtn = document.getElementById("clearStoreSearch");
    const grid = document.getElementById("storesGrid");
    const noResults = document.getElementById("noResults");
    const countNumber = document.getElementById("visibleCountNumber");
    const resetBtn = document.getElementById("resetSearchBtn");

    if (searchInput && grid) {
      const cards = grid.querySelectorAll(".store-card");

      function performSearch(query) {
        let visibleCount = 0;
        cards.forEach(function(card) {
          const name = card.getAttribute("data-name") || "";
          const address = card.getAttribute("data-address") || "";
          const city = card.getAttribute("data-city") || "";

          if (name.includes(query) || address.includes(query) || city.includes(query)) {
            card.style.display = "flex";
            visibleCount++;
          } else {
            card.style.display = "none";
          }
        });

        if (countNumber) {
          countNumber.textContent = visibleCount;
        }

        if (clearBtn) {
          clearBtn.style.display = query.length > 0 ? "flex" : "none";
        }

        if (noResults) {
          noResults.style.display = visibleCount === 0 ? "flex" : "none";
        }
      }

      searchInput.addEventListener("input", function(e) {
        const query = e.target.value.toLowerCase().trim();
        performSearch(query);
      });

      if (clearBtn) {
        clearBtn.addEventListener("click", function() {
          searchInput.value = "";
          performSearch("");
          searchInput.focus();
        });
      }

      if (resetBtn) {
        resetBtn.addEventListener("click", function() {
          searchInput.value = "";
          performSearch("");
          searchInput.focus();
        });
      }
    }

    document.querySelectorAll(".copy-btn").forEach(function(btn) {
      btn.addEventListener("click", function() {
        const text = this.getAttribute("data-copy");
        const copyTextEl = this.querySelector(".copy-text");
        if (navigator.clipboard && text) {
          navigator.clipboard.writeText(text).then(() => {
            const originalText = copyTextEl ? copyTextEl.textContent : "Copiar";
            if (copyTextEl) copyTextEl.textContent = "¡Copiado!";
            this.style.background = "#dcfce7";
            this.style.borderColor = "#86efac";
            this.style.color = "#166534";
            setTimeout(() => {
              if (copyTextEl) copyTextEl.textContent = originalText;
              this.style.background = "";
              this.style.borderColor = "";
              this.style.color = "";
            }, 1800);
          });
        }
      });
    });
  })();
</script>
